/**
 * Three sounds, and not one byte of audio.
 *
 * > "LE SON, SI TU PEUX : trois sons courts, pas plus — le cran du curseur, la
 * > mise poussée, le dénouement. Embarqués dans le build, aucun appel réseau,
 * > coupés par défaut avec un bouton pour activer."
 *
 * ## Synthesised, not shipped
 *
 * They are generated by the Web Audio API at the moment they play: two
 * oscillators and an envelope each. That satisfies the project's first rule
 * absolutely rather than approximately — there is no file to fetch, no data
 * URI to inflate the bundle, and `npm run check:offline` stays at twelve
 * same-origin requests because nothing was added to request.
 *
 * It also means the sounds are *described* rather than recorded, so they are
 * in the repository as a few lines anyone can read and change, which is the
 * same reason every other constant in this project is a named number.
 *
 * ## Off by default, and off means silent
 *
 * No context is created until the player turns sound on, so a player who
 * never does has no audio graph at all. Browsers also refuse to start one
 * before a gesture; the first click after enabling is what starts it, and
 * nothing here throws if it does not.
 */

export type Cue = 'detent' | 'stake' | 'reveal'

let context: AudioContext | null = null
let enabled = false

/** Turn sound on or off. Off tears the context down rather than muting it. */
export function setSoundEnabled(on: boolean): void {
  enabled = on
  if (!on && context !== null) {
    void context.close().catch(() => {})
    context = null
  }
}

export function isSoundEnabled(): boolean {
  return enabled
}

function ensureContext(): AudioContext | null {
  if (!enabled) return null
  if (context !== null) return context
  try {
    const Ctor =
      globalThis.AudioContext ??
      (globalThis as { webkitAudioContext?: typeof AudioContext }).webkitAudioContext
    if (Ctor === undefined) return null
    context = new Ctor()
    return context
  } catch {
    // A browser that will not give us audio is a browser that plays silently.
    return null
  }
}

/**
 * The three cues, as frequency, length and shape.
 *
 * Deliberately short and deliberately quiet. The detent in particular fires on
 * every notch of the dial, so it is 30 ms of a soft click — anything longer or
 * louder becomes a rattle the first time somebody drags the handle across the
 * whole track.
 */
const CUES: Record<Cue, { readonly from: number; readonly to: number; readonly ms: number; readonly gain: number }> = {
  // A notch. Dry, high, almost percussive.
  detent: { from: 880, to: 760, ms: 30, gain: 0.05 },
  // Chips pushed onto the table: lower, with a little fall to it.
  stake: { from: 320, to: 180, ms: 140, gain: 0.09 },
  // The card turning. The only one with any length, because it is the only
  // one that is a moment rather than a confirmation.
  reveal: { from: 200, to: 540, ms: 420, gain: 0.08 },
}

/**
 * Play one cue. Silent and free when sound is off.
 *
 * Never throws and never awaits: a sound that failed must not interrupt the
 * decision it was decorating.
 */
export function play(cue: Cue): void {
  const audio = ensureContext()
  if (audio === null) return
  try {
    const spec = CUES[cue]
    const now = audio.currentTime
    const seconds = spec.ms / 1000

    const oscillator = audio.createOscillator()
    oscillator.type = 'triangle'
    oscillator.frequency.setValueAtTime(spec.from, now)
    oscillator.frequency.exponentialRampToValueAtTime(spec.to, now + seconds)

    const envelope = audio.createGain()
    // A hard attack and an exponential tail, which is what a struck object
    // does. A linear fade reads as a synthesiser.
    envelope.gain.setValueAtTime(0.0001, now)
    envelope.gain.exponentialRampToValueAtTime(spec.gain, now + 0.004)
    envelope.gain.exponentialRampToValueAtTime(0.0001, now + seconds)

    oscillator.connect(envelope).connect(audio.destination)
    oscillator.start(now)
    oscillator.stop(now + seconds + 0.02)
  } catch {
    // As above.
  }
}
